-- Partial reverse: puts both profiles back under review. Full rollback of the text: restore the two rows from the recovery
-- point's DB backup. Generated by Build-Sql.py.
\set ON_ERROR_STOP on
UPDATE editorial_profiles SET review_required = true, updated_at = now() WHERE publisher_id IN (9049, 8999);
SELECT 'reversed|' || publisher_id || '|review ' || review_required FROM editorial_profiles WHERE publisher_id IN (9049, 8999) ORDER BY 1;
